"""Author A2-U10 only; preserve previous sessions and lexical meanings."""
import json,copy,re,sys
from pathlib import Path
ROOT=Path(__file__).resolve().parents[4]
KIT=ROOT/'plans/daily-practice-authoring'
OUT=Path(__file__).parent/'packages/A2'
A1=Path(__file__).parent/'packages/A1'
PRE=Path(__file__).parent/'packages/PRE_A1'
level=json.loads((KIT/'levels/A2.plan.json').read_text())['level']
plan=level['units'][9]
W={}
for source in [OUT/'A2-U09.v1.json',OUT/'A2-U08.v1.json',OUT/'A2-U07.v1.json',OUT/'A2-U06.v1.json',OUT/'A2-U05.v1.json',OUT/'A2-U04.v1.json',OUT/'A2-U03.v1.json',OUT/'A2-U02.v1.json',OUT/'A2-U01.v1.json']+[A1/f'A1-U{n:02}.v1.json' for n in range(20,0,-1)]+[PRE/f'PRE_A1-U{n:02}.v1.json' for n in range(20,1,-1)]+[KIT/'examples/PRE_A1-U01.v2.json']:
 for s in json.loads(source.read_text())['sessions']:
  for w in s['vocabulary']:W.setdefault(w['id'],copy.deepcopy(w))
for w in W.values():
 if 'example' not in w:w['example']=dict(fr=w['fr'],ru=w['ru'][0],transcription_ru=w['transcription_ru'])
OLD=set(W);FIRST={};S=[]
U='A2.U10.UNDERSTAND';A='A2.U10.APPLY'
OBJECTIVES={o['id']:o for u in level['units'] for o in u['objectives']}

def ru(t): return dict(text=t,text_lang='ru')

def fr(t,p): return dict(text=t,text_lang='fr',transcription_ru=p)

def ex(f,r,p): return dict(fr=f,ru=r,transcription_ru=p)

def sound(f,p): return dict(text=f,transcription_ru=p,lang='fr-FR',asset_id=None)

def wc(w): return fr(W[w]['fr'],W[w]['transcription_ru'])

def fb(g,b): return dict(correct=g,incorrect=b)

def opts(v): return [dict(id=f'c{i}',**(ru(t) if isinstance(t,str) else t)) for i,t in enumerate(v)]

def rev(i,p,cs,a,g,b): return dict(id=i,type='single_choice',instruction='Выберите один ответ.',prompt=p,choices=opts(cs),correct_choice_id=f'c{a}',feedback=fb(g,b))

def start(n,d,vs):
 p=plan['sessions'][n-1]; s={k:copy.deepcopy(p[k]) for k in ['id','title','order','kind','prerequisite_ids']}
 s.update(version=1,level='A2',unit_id=plan['id'],description=d,duration_minutes=7,objectives=copy.deepcopy(plan['objectives']),skills=[],vocabulary=[copy.deepcopy(W[w]) for w in vs],tasks=[],introductions=[]); S.append(s); return s

def base(s,sk,gs,vs,av,ins,p,g,b):
 for o in gs:
  if o not in [x['id'] for x in s['objectives']]: s['objectives'].append(copy.deepcopy(OBJECTIVES[o]))
 if sk not in s['skills']: s['skills'].append(sk)
 t=dict(id=f'Q{len(s["tasks"])+1:02}',instruction=ins,prompt=p,feedback=fb(g,b),objective_ids=gs,skill=sk,vocabulary_ids=vs,assessed_vocabulary_ids=av); s['tasks'].append(t); return t

def choose(s,sk,gs,vs,av,ins,p,cs,a,g,b):
 t=base(s,sk,gs,vs,av,ins,p,g,b); t.update(type='single_choice',choices=opts(cs),correct_choice_id=f'c{a}'); return t

def listen(s,gs,vs,av,q,f,p,cs,a,g,b):
 return choose(s,'listening',gs,vs,av,'Прослушайте и выберите ответ.',dict(**ru(q),audio=sound(f,p)),cs,a,g,b)

def intro(s,n,t,vs,ns=(),au=None):
 i=dict(id=f'I{len(s["introductions"])+1:02}',before_task_id=f'Q{n:02}',text=t,vocabulary_ids=vs)
 if ns:i['pronunciation_notes']=[dict(fr=f,transcription_ru=p) for f,p in ns]
 if au:i['audio']=sound(*au)
 s['introductions'].append(i)

def pairs(s,gs,rows,g,b):
 vs=[w for w,r in rows]; t=base(s,'vocabulary',gs,vs,vs,'Соедините каждую карточку с её значением.',ru('Используйте все карточки по одному разу.'),g,b)
 t.update(type='matching_pairs',left_items=[dict(id=f'l{i}',**wc(w)) for i,(w,r) in enumerate(rows)],right_items=[dict(id=f'r{i}',**ru(r)) for i,(w,r) in reversed(list(enumerate(rows)))],correct_pairs=[dict(left_id=f'l{i}',right_id=f'r{i}',assessed_vocabulary_ids=[w]) for i,(w,r) in enumerate(rows)])

def order(s,gs,vs,av,ins,ts,f,p,g,b):
 t=base(s,'sentence_building',gs,vs,av,ins,ru('Нажимайте на карточки в нужном порядке.'),g,b); tokens=[dict(id=f't{i}',**fr(f,p)) for i,(f,p) in enumerate(ts)]
 t.update(type='word_order',tokens=list(reversed(tokens)),accepted_orders=[[x['id'] for x in tokens]],completed_phrases=[dict(fr=f,transcription_ru=p)])

def fill(s,gs,vs,av,ins,bef,bp,aft,ap,cs,a,f,p,g,b):
 if aft=='.' and not ap:aft='';f=f.removesuffix('.');p=p.removesuffix('.')
 t=base(s,'vocabulary',gs,vs,av,ins,ru('Выберите одну карточку для пропуска.'),g,b)
 t.update(type='fill_blank',input_mode='choice',text_before=bef,text_before_transcription_ru=bp,text_after=aft,text_after_transcription_ru=ap,choices=opts(cs),correct_choice_id=f'c{a}',completed_phrases=[dict(fr=f,transcription_ru=p)])

 return t

def page(s,blocks):
 s['public_page']=dict(slug=s['id'].lower().replace('_','-'),summary=s['description'],seo_title=s['title']+' — практика французского',seo_description=s['description'],explanation_blocks=[dict(heading=h,paragraphs=ps,examples=es) for h,ps,es in blocks])

def grammar(t):
 t['skill']='grammar'
 return t

def phrase_pairs(s,gs,rows,g,b):
 vs=list(dict.fromkeys(w for f,p,r,ws,av in rows for w in ws)); avs=list(dict.fromkeys(w for f,p,r,ws,av in rows for w in av))
 t=base(s,'vocabulary',gs,vs,avs,'Соедините реплику или выражение с его смыслом.',ru('Используйте каждую карточку один раз.'),g,b)
 t.update(type='matching_pairs',left_items=[dict(id=f'l{i}',**fr(f,p)) for i,(f,p,r,ws,av) in enumerate(rows)],right_items=[dict(id=f'r{i}',**ru(r)) for i,(f,p,r,ws,av) in reversed(list(enumerate(rows)))],correct_pairs=[dict(left_id=f'l{i}',right_id=f'r{i}',assessed_vocabulary_ids=av) for i,(f,p,r,ws,av) in enumerate(rows)])
 return t

def addword(i,key,f,r,p,e,n,reviews):
 W[i]=dict(id=i,lexeme_key=key,fr=f,ru=[r],transcription_ru=p,example=e,review_items=reviews);FIRST[i]=n
def word(i,key,f,r,p,n,example,meaning_choices,meaning_answer,use_prompt,use_choices,use_answer):
 addword(i,key,f,r,p,example,n,[rev(i+'-meaning',fr(f,p),meaning_choices,meaning_answer,'Правильное значение: '+r+'.','Нужно значение «'+r+'»; остальные варианты называют другое.'),rev(i+'-use',ru(use_prompt),[fr(a,b) for a,b in use_choices],use_answer,'Выбран вариант, который сохраняет условие ситуации.','Нужная реплика: '+use_choices[use_answer][0]+'. '+use_prompt)])
word('plus-comparatif','fr:plus:greater-degree-comparison','plus','более: степень признака в сравнении','плю',1,ex('L’appartement près du parc est plus calme que l’appartement près de la gare.','Квартира у парка тише квартиры у вокзала.','лапартёма(н) прэ дю парк э плю кальм кё лапартёма(н) прэ дё ла га́р'),['Более: усиление признака в сравнении','Менее: уменьшение степени признака','Одинаковая степень'],0,'Выберите: квартира у парка более тихая, чем квартира у вокзала.',[('L’appartement près du parc est moins calme que l’appartement près de la gare.','лапартёма(н) прэ дю парк э муэ(н) кальм кё лапартёма(н) прэ дё ла га́р'),('L’appartement près du parc est plus calme que l’appartement près de la gare.','лапартёма(н) прэ дю парк э плю кальм кё лапартёма(н) прэ дё ла га́р'),('L’appartement près du parc est aussi calme que l’appartement près de la gare.','лапартёма(н) прэ дю парк э тоси кальм кё лапартёма(н) прэ дё ла га́р')],1)
word('aussi-comparatif','fr:aussi:equality-comparison','aussi','такой же: равная степень признака в сравнении','оси́',1,ex('L’appartement près du parc est aussi lumineux que l’appartement près de la gare.','Квартира у парка такая же светлая, как квартира у вокзала.','лапартёма(н) прэ дю парк э тоси люминё кё лапартёма(н) прэ дё ла га́р'),['Более светлый','Такой же по степени признака','Слишком светлый'],1,'Нужно сказать, что две квартиры одинаково светлые.',[('L’appartement près du parc est aussi lumineux que l’appartement près de la gare.','лапартёма(н) прэ дю парк э тоси люминё кё лапартёма(н) прэ дё ла га́р'),('L’appartement près du parc est plus lumineux que l’appartement près de la gare.','лапартёма(н) прэ дю парк э плю люминё кё лапартёма(н) прэ дё ла га́р'),('L’appartement près du parc est moins lumineux que l’appartement près de la gare.','лапартёма(н) прэ дю парк э муэ(н) люминё кё лапартёма(н) прэ дё ла га́р')],0)
word('le-plus','fr:le-plus:highest-degree','le plus','самый: наибольшая степень признака среди сравниваемых','лё плю',2,ex('Cet appartement est le plus calme des trois.','Эта квартира самая тихая из трёх.','сэт апартёма(н) э лё плю кальм дэ труа́'),['Такой же','Менее','Самый среди сравниваемых'],2,'Выберите: эта квартира самая тихая из трёх.',[('Cet appartement est aussi calme que l’autre.','сэт апартёма(н) э тоси кальм кё ло́тр'),('Cet appartement est le plus calme des trois.','сэт апартёма(н) э лё плю кальм дэ труа́'),('Cet appartement est moins calme que l’autre.','сэт апартёма(н) э муэ(н) кальм кё ло́тр')],1)
word('meilleur','fr:meilleur:better-quality','meilleur','лучше по качеству; с артиклем в изученной модели — лучший','мэйё́р',2,ex('Ce café est meilleur que l’autre.','Этот кофе лучше по качеству, чем другой.','сё кафэ э мэйёр кё ло́тр'),['Дороже по цене','Такой же по качеству','Лучше по качеству'],2,'Нужно сказать, что этот кофе лучше по качеству, чем другой.',[('Ce café est moins cher que l’autre.','сё кафэ э муэ(н) шэр кё ло́тр'),('Ce café est meilleur que l’autre.','сё кафэ э мэйёр кё ло́тр'),('Ce café est aussi cher que l’autre.','сё кафэ э тоси шэр кё ло́тр')],1)
word('avantage','fr:avantage:benefit-of-option','un avantage','преимущество варианта','э(н) нава(н)та́ж',3,ex('Cet appartement est calme. C’est un avantage.','Эта квартира тихая. Это преимущество.','сэт апартёма(н) э ка́льм. сэ тэ(н) нава(н)та́ж'),['Преимущество','Неудобство','Дополнительный платёж'],0,'Назовите тишину преимуществом варианта.',[('Cet appartement est calme. C’est un avantage.','сэт апартёма(н) э ка́льм. сэ тэ(н) нава(н)та́ж'),('Cet appartement est calme. C’est un inconvénient.','сэт апартёма(н) э ка́льм. сэ тэ(н) нэ(н)ко(н)вэнья́(н)'),('Les charges ne sont pas incluses.','лэ шарж нё со(н) па э(н)клю́з')],0)
word('inconvenient','fr:inconvenient:drawback-of-option','un inconvénient','неудобство, недостаток варианта','э(н) нэ(н)ко(н)вэнья́(н)',3,ex('Le bruit est un inconvénient.','Шум — неудобство.','лё брюи э тэ(н) нэ(н)ко(н)вэнья́(н)'),['Преимущество','Неудобство варианта','Время встречи'],1,'Выберите оценку шума как неудобства.',[('Le bruit est un avantage.','лё брюи э тэ(н) нава(н)та́ж'),('Le bruit est un inconvénient.','лё брюи э тэ(н) нэ(н)ко(н)вэнья́(н)'),('Le rendez-vous est mardi.','лё ра(н)дэ ву э марди́')],1)
word('assez','fr:assez:sufficient-degree','assez','достаточно: нужная степень признака достигнута','асэ́',4,ex('L’appartement est assez grand.','Квартира достаточно большая.','лапартёма(н) э тасэ гра́(н)'),['Слишком: степень мешает выбору','Менее: сравнение двух вариантов','Достаточно: нужная степень достигнута'],2,'Выберите: квартира достаточно тихая, а не слишком шумная.',[('L’appartement est trop bruyant.','лапартёма(н) э тро брюийа́(н)'),('L’appartement est assez calme.','лапартёма(н) э тасэ ка́льм'),('L’appartement est plus bruyant que l’autre.','лапартёма(н) э плю брюийа(н) кё ло́тр')],1)
for w,g,b in [('plus-comparatif','Степень тишины у квартиры у парка выше.','Равенство и меньшая степень тишины меняют сравнение.'),('aussi-comparatif','Две квартиры названы одинаково светлыми.','Большая или меньшая освещённость не сохраняет равенство.'),('le-plus','Названа самая тихая квартира среди трёх.','Сравнение только с другим вариантом и равенство не устанавливают наибольшую степень среди трёх.'),('meilleur','Сравнивается качество кофе, и оно оценено выше.','Сравнение цены не является оценкой качества.'),('avantage','Тишина оценена как преимущество.','Неудобство — противоположная оценка, а условие о платежах — другое сведение.'),('inconvenient','Шум назван недостатком варианта.','Преимущество меняет оценку на противоположную; время встречи её не выражает.'),('assez','Тишины достаточно для потребности, выраженной в ситуации.','Чрезмерный шум и сравнительно больший шум не означают достаточную тишину.')]:W[w]['review_items'][1]['feedback']=fb(g,b)
# The meaning of a comparison function is read inside a full model.
for w,f,p in [('plus-comparatif','Cet appartement est plus calme que l’autre.','сэт апартёма(н) э плю кальм кё ло́тр'),('aussi-comparatif','Cet appartement est aussi calme que l’autre.','сэт апартёма(н) э тоси кальм кё ло́тр'),('le-plus','Cet appartement est le plus calme des trois.','сэт апартёма(н) э лё плю кальм дэ труа́')]:W[w]['review_items'][0]['prompt']=fr(f,p)

def reading(s,gs,vs,av,q,f,p,cs,a,g,b):return choose(s,'reading',gs,vs,av,q,fr(f,p),cs,a,g,b)
def vocabulary(s,gs,vs,av,q,cs,a,g,b):return choose(s,'vocabulary',gs,vs,av,q,ru('Выберите реплику по всем условиям.'),[fr(f,p) for f,p in cs],a,g,b)
def warmup(s,unit,lesson,task):
 prior=json.loads((OUT/f'{unit}.v1.json').read_text());t=copy.deepcopy(next(t for t in prior['sessions'][lesson-1]['tasks'] if t['id']==task));t['id']=f'Q{len(s["tasks"])+1:02}';s['tasks'].append(t)
 for o in t['objective_ids']:
  if o not in {x['id'] for x in s['objectives']}:s['objectives'].append(copy.deepcopy(OBJECTIVES[o]))

s=start(1,'Сравните квартиры по одному признаку: более, менее или в той же степени тихие и светлые.',[])
warmup(s,'A2-U09',5,'Q02')
intro(s,2,'Plus + признак + que означает «более …, чем»; знакомое moins + признак + que — «менее …, чем». Aussi + признак + que означает «такой же …, как». Сравниваем отдельно тишину и освещённость: одинаковая освещённость не означает одинаковую тишину. В выбранных сочетаниях plus calme и plus lumineux конечный согласный слова plus не произносится. Здесь учим сравнительное значение, а не все значения слова.',['plus-comparatif','aussi-comparatif','moins'],[('Plus','плю'),('que','кё'),('moins','муэ́(н)'),('Aussi','оси́'),('plus calme','плю ка́льм'),('plus lumineux','плю люминё́'),('plus','плю')],('L’appartement près du parc est plus calme que l’appartement près de la gare. Il est aussi lumineux que l’appartement près de la gare.','лапартёма(н) прэ дю парк э плю кальм кё лапартёма(н) прэ дё ла га́р. иль э тоси люминё кё лапартёма(н) прэ дё ла га́р.'))
phrase_pairs(s,[U],[('Plus calme que l’autre','плю кальм кё ло́тр','Более тихий, чем другой',['plus-comparatif','calme','autre'],['plus-comparatif']),('Moins calme que l’autre','муэ(н) кальм кё ло́тр','Менее тихий, чем другой',['moins','calme','autre'],['moins']),('Aussi calme que l’autre','оси кальм кё ло́тр','Такой же тихий, как другой',['aussi-comparatif','calme','autre'],['aussi-comparatif'])],'Различены большая, меньшая и равная степень тишины.','Сравнивайте направление по одному и тому же признаку; равенство не означает большую степень.')
listen(s,[U],['appartement','pres-de','parc','gare','plus-comparatif','calme','aussi-comparatif','lumineux','moins','bruyant','choisir','je-voudrais'],['plus-comparatif','calme','aussi-comparatif','lumineux'],'Какие два сравнения прямо названы?', 'L’appartement près du parc est plus calme que l’appartement près de la gare. Il est aussi lumineux que l’appartement près de la gare. Il est moins bruyant. Je voudrais choisir l’appartement près du parc.','лапартёма(н) прэ дю парк э плю кальм кё лапартёма(н) прэ дё ла га́р. иль э тоси люминё кё лапартёма(н) прэ дё ла га́р. иль э муэ(н) брюийа́(н). жё вудрэ шуазир лапартёма(н) прэ дю па́рк.',['У парка тише; освещённость одинаковая','У парка шумнее; освещённость одинаковая','У парка тише и светлее'],0,'У парка тише, а освещённость двух квартир одинакова.','Не переносите направление сравнения тишины на освещённость.')
